    kind: mediaType === CSV_MEDIA_TYPE ? "csv_upload" : "xlsx_upload",
    fileName,
    mediaType,
    byteSize: bytes.byteLength,
    contentSha256: createHash("sha256").update(bytes).digest("hex"),
  };
}

