  /** The uploading user (uploads); null for a webhook or connector batch (`import_batch_source_shape`). */
  readonly createdBy: string | null;
  readonly audit: AuditContext;
  /**
   * The caller's commit-time authorization re-check (p6-work-split §2 rule 4), run inside the transaction after the
   * lock and before any write: for an upload, `import.create` in the batch's transformation through `ReadScope`.
   */
  readonly recheck?: (tx: Tx) => Promise<void>;
}

const formSchemaChanged = () =>
  new HttpProblem({
    status: 409,
    type: PROBLEM_TYPES.invalidTransition,
    code: "import.form_schema_changed",
    title: "Conflict",
    detail: "The form schema of this transformation changed while the file was checked. Upload the file again.",
  });

const ROW_CHUNK = 400;

/**
 * Stages a prepared import inside `tx` (ADR-0056 §2, §5). Returns the `staged` batch. The batch id is locked with the
 * importCommit advisory-lock class (ADVISORY_LOCK_CLASSES.importCommit). The target's existing keys are read inside the transaction, so a row is classified
 * `duplicate_committed` against the data as it is at staging; the DG4 unique key remains the backstop at commit.
 */
export async function stageImportInTx(
  tx: Tx,
  prepared: PreparedImport,
  options: StageImportOptions,
): Promise<ImportBatchRow> {
  const { context, target } = prepared;
  const id = uuidv7();
  await sql`SELECT pg_advisory_xact_lock(${ADVISORY_LOCK_CLASSES.importCommit}::int4, hashtext(${id}::text))`.execute(
    tx,
  );
  if (options.recheck) await options.recheck(tx);
  const pinned = await sql<{
    v: string;
  }>`SELECT p5_form_schema_version_for(${context.transformationId}::uuid) AS v`.execute(tx);
  if (pinned.rows[0]?.v !== context.formSchemaVersionId) throw formSchemaChanged();

  const s = options.source;
  const machine = s.kind === "webhook" || s.kind === "connector";
  await tx
    .insertInto("import_batch")
    .values({
      id,
      organization_id: context.organizationId,
      transformation_id: context.transformationId,
      target_kind: target.kind,
      template_version: target.templateVersion,
      form_schema_version_id: context.formSchemaVersionId,
      source_kind: s.kind,
      connector_id: machine ? s.connectorId : null,
      integration_run_id: s.kind === "connector" ? s.integrationRunId : null,
      webhook_receipt_id: s.kind === "webhook" ? s.webhookReceiptId : null,
      file_name: machine ? null : s.fileName,
      media_type: machine ? (s.kind === "webhook" ? "application/json" : null) : s.mediaType,
      byte_size: machine ? null : s.byteSize,
      content_sha256: machine ? null : s.contentSha256,
      commit_mode: machine ? s.commitMode : "manual",
      on_behalf_of_user_id: machine ? s.onBehalfOfUserId : null,
      created_by: options.createdBy,
      updated_by: options.createdBy,
    })
    .execute();
  await audit(tx, options.audit, {
    action: "import_batch.created",
    recordType: "import_batch",
    recordId: id,
    organizationId: context.organizationId,
    transformationId: context.transformationId,
    newVersion: 1,
    changes: {
      template_version: { from: null, to: target.templateVersion },
      source_kind: { from: null, to: s.kind },
      file_name: { from: null, to: machine ? null : s.fileName },
      status: { from: null, to: "staging" },
    },
  });

  const keys = candidateKeys(prepared.rows);
  const committed = keys.length === 0 ? new Map() : await target.existingKeys({ ...context, db: tx }, keys);
  const classified = classifyDuplicates(prepared.rows, committed);
  await insertRows(tx, id, context, classified);
  const counts = countRows(classified);

  const staged = await tx
    .updateTable("import_batch")
    .set({
      status: "staged",
      rows_total: counts.total,
      rows_valid: counts.valid,
      rows_invalid: counts.invalid,
      rows_duplicate: counts.duplicate,
      version: 2,
      updated_at: sql<Date>`now()`,
      updated_by: options.createdBy,
    })
    .where("id", "=", id)
    .where("version", "=", 1)
    .returningAll()
    .executeTakeFirstOrThrow();
  await audit(tx, options.audit, {
    action: "import_batch.staged",
    recordType: "import_batch",
    recordId: id,
    organizationId: context.organizationId,
    transformationId: context.transformationId,
    priorVersion: 1,
    newVersion: 2,
    changes: {
      status: { from: "staging", to: "staged" },
      rows_total: { from: null, to: counts.total },
      rows_valid: { from: null, to: counts.valid },
      rows_invalid: { from: null, to: counts.invalid },
      rows_duplicate: { from: null, to: counts.duplicate },
    },
  });
  return staged;
}

async function insertRows(tx: Tx, batchId: string, context: ImportTargetContext, rows: readonly ClassifiedRow[]) {
  const idByRowNumber = new Map<number, string>();
  const values = rows.map((r) => {
    const rowId = uuidv7();
    idByRowNumber.set(r.rowNumber, rowId);
    return {
      id: rowId,
      organization_id: context.organizationId,
      transformation_id: context.transformationId,
      import_batch_id: batchId,
      row_number: r.rowNumber,
      source_record_id: r.sourceRecordId,
      raw: JSON.stringify(rawForStorage(r.raw)),
      normalized: r.normalized === null ? null : JSON.stringify(r.normalized),
      duplicate_key: r.duplicateKey,
      validation_status: r.validationStatus,
      duplicate_of_row_id: r.duplicateOfRowNumber === null ? null : idByRowNumber.get(r.duplicateOfRowNumber)!,
      reasons: JSON.stringify(r.reasons.map((x) => ({ code: x.code, field: x.field ?? null, params: x.params ?? {} }))),
    };
  });
  // Row-number order: an in-batch duplicate's first valid row is always inserted before it (trigger import_row_duplicate_of).
  for (let i = 0; i < values.length; i += ROW_CHUNK)
    await tx
      .insertInto("import_row")
      .values(values.slice(i, i + ROW_CHUNK))
      .execute();
}

/** `stageImportInTx` in its own transaction (uploads). */
export function stageImport(db: Db, prepared: PreparedImport, options: StageImportOptions): Promise<ImportBatchRow> {
  return db.transaction().execute((tx) => stageImportInTx(tx, prepared, options));
}

/** The engine's own reasons for one row and the fields they concern (the target sees those fields as null). */
export interface CellCheck {
  readonly reasons: readonly ImportRowReason[];
  readonly refusedFields: ReadonlySet<string>;
  /** The cells the target receives: refused cells replaced by null. */
  readonly cells: ImportCells;
  /** `source_record_id` when it fits the column (≤ 200 characters), else null. */
  readonly sourceRecordId: string | null;
}

/**
 * ADR-0056 §3-§5, the rules that do not depend on the target: a formula cell is `import.row.formula_cell` (D-195 Q11:
 * never its cached value); a cell whose source value was not text (a webhook's JSON number) is
 * `import.row.value_not_decimal` (ADR-0056 §7), never coerced; a cell over 4,000 characters is
 * `import.row.text_too_long`; a cell with U+0000 or a lone surrogate is `import.row.text_invalid_character` (the shared `hasInvalidCharacter` rule, ADR-0052 §2); a
 * `source_record_id` over 200 characters is `import.row.source_record_id_too_long` (proposed in the handback: the
 * column holds 200). Formula-like CSV text (`=`, `+`, `-`, `@` first) is NOT refused: it is imported as text (D-195
 * Q11) and neutralised on any later export (ADR-0046).
 */
export function checkCells(row: ParsedRow): CellCheck {
  const reasons: ImportRowReason[] = [];
  const refused = new Set<string>();
  const cells = new Map(Object.entries(row.cells));
  const refuse = (code: string, field: string, params: Record<string, string> = {}) => {
    reasons.push({ code, field, params: { field, ...params } });
    refused.add(field);
    cells.set(field, null);
  };
  for (const field of row.formulaColumns) refuse("import.row.formula_cell", field);
  for (const field of row.nonTextColumns ?? [])
    if (!refused.has(field))
      refuse("import.row.value_not_decimal", field, { value: truncateText(cellValue(row.cells, field) ?? "", 200) });
  for (const [field, value] of Object.entries(row.cells)) {
    if (value === null || refused.has(field)) continue;
    if (value.length > IMPORT_LIMITS.cellChars) refuse("import.row.text_too_long", field);
    else if (hasInvalidCharacter(value)) refuse("import.row.text_invalid_character", field);
  }
  let sourceRecordId = cells.get(SOURCE_RECORD_ID_COLUMN) ?? null;
  if (sourceRecordId !== null && sourceRecordId.length > SOURCE_RECORD_ID_MAX) {
    refuse("import.row.source_record_id_too_long", SOURCE_RECORD_ID_COLUMN);
    sourceRecordId = null;
  }
  return { reasons, refusedFields: refused, cells: Object.fromEntries(cells), sourceRecordId };
}

/**
 * The row's final verdict: the engine's reasons first, then the target's reasons for the other fields (a target
 * reason on a refused field repeats the engine's and is dropped). At most 20 reasons are stored (0105).
 */
export function mergeVerdict(check: CellCheck, verdict: RowVerdict): RowVerdict {
  if (check.reasons.length === 0) {
    if (verdict.valid) return verdict;
    return {
      valid: false,
      reasons: verdict.reasons.slice(0, IMPORT_LIMITS.reasonsPerRow),
      duplicateKey: verdict.duplicateKey,
    };
  }
  const targetReasons = verdict.valid
    ? []
    : verdict.reasons.filter((r) => r.field === undefined || r.field === null || !check.refusedFields.has(r.field));
  return {
    valid: false,
    reasons: [...check.reasons, ...targetReasons].slice(0, IMPORT_LIMITS.reasonsPerRow),
    duplicateKey: verdict.duplicateKey,
  };
}

// ------------------------------------------------------------------------------------------------ raw cells

const jsonBytes = (value: unknown): number => Buffer.byteLength(JSON.stringify(value), "utf8");

/**
 * The cells as stored in `import_row.raw` (0105 CHECK: ≤ 50 keys, ≤ 32 KiB of JSON, values text or null). A cell over
 * 4,000 characters is stored cut to 4,000 (its row is invalid with `import.row.text_too_long`); if the row still
 * exceeds the column, its longest cells are cut further, through `truncateText` only (p6-work-split §2 rule 1). The
 * row's verdict was taken on the full cells; the cut applies only to the stored display copy.
 */
export function rawForStorage(cells: ImportCells): Record<string, string | null> {
  const raw = new Map(
    Object.entries(cells).map(([k, v]) => [k, v === null ? null : truncateText(v, IMPORT_LIMITS.cellChars)]),
  );
  // jsonb's text form adds a space after each ':' and ','; leave room for it and for escapes that grow on output.
  const budget = IMPORT_LIMITS.rawBytes - 4 * raw.size - 64;
  while (jsonBytes(Object.fromEntries(raw)) > budget) {
    let longest: [string, string] | null = null;
    for (const [k, v] of raw) if (v !== null && (longest === null || v.length > longest[1].length)) longest = [k, v];
    if (longest === null) break;
    raw.set(longest[0], truncateText(longest[1], Math.floor(longest[1].length / 2)));
  }
  return Object.fromEntries(raw);
}

