{
  "name": "@mth/reporting",
  "version": "0.1.0",
  "private": true,
  "description": "Report exporters (PDF, DOCX, XLSX, PPTX, CSV), bundled fonts and export storage (ADR-0045, ADR-0046)",
  "license": "UNLICENSED",
  "type": "module",
  "exports": {
    ".": {
      "@mth/source": "./src/index.ts",
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./storage": {
      "@mth/source": "./src/storage.ts",
      "types": "./dist/storage.d.ts",
      "default": "./dist/storage.js"
    }
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json"
  },
  "dependencies": {
    "@fontsource/ibm-plex-sans": "5.2.6",
    "@fontsource/ibm-plex-sans-arabic": "5.2.6",
    "@mth/shared": "workspace:*",
    "bidi-js": "1.1.0",
    "decimal.js": "10.6.0",
    "docx": "9.8.1",
// @mth/reporting (ADR-0002 reservation, ADR-0046 §1): the pure export renderers and the export-file store. The worker
// imports this entry; the API imports only the dependency-free `@mth/reporting/storage` subpath, so no renderer library
// is ever loaded by the API process.
export {
  FORMULA_TRIGGER_CHARACTERS,
  neutralizeSpreadsheetText,
  startsLikeFormula,
  type NeutralizedText,
} from "./injection.ts";
export {
  createLabels,
  DEFAULT_PRODUCT_NAMES,
  fallbackLabel,
  FRAME_LABELS,
  type ExportLanguage,
  type LabelTable,
  type Labels,
} from "./labels.ts";
export {
  EXPORT_CONTENT_TYPES,
  EXPORT_FORMATS,
  formatAsOf,
  issueLine,
  RenderError,
  type ExportFormat,
  type RenderOptions,
  type RenderResult,
  type SnapshotIdentity,
} from "./model.ts";
export { csvField, renderCsv } from "./csv.ts";
// ------------------------------------------------------------------------------------------------ a tiny XLSX writer

type Cell = string | { n: string } | { f: string; v: string };

function tinyXlsx(rows: readonly (readonly Cell[])[]): Uint8Array {
  const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  const sheet = rows
    .map((cells, r) => {
      const cs = cells
        .map((c, i) => {
          const ref = `${String.fromCharCode(65 + i)}${r + 1}`;
          if (typeof c === "string") return `<c r="${ref}" t="inlineStr"><is><t>${esc(c)}</t></is></c>`;
          if ("f" in c) return `<c r="${ref}"><f>${esc(c.f)}</f><v>${c.v}</v></c>`;
          return `<c r="${ref}"><v>${c.n}</v></c>`;
        })
        .join("");
      return `<row r="${r + 1}">${cs}</row>`;
    })
    .join("");
  const parts: Array<[string, string]> = [
    [
      "[Content_Types].xml",
      `<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="xml" ContentType="application/xml"/></Types>`,
    ],
    [
      "xl/workbook.xml",
      `<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets></workbook>`,
    ],
    [
      "xl/_rels/workbook.xml.rels",
      `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`,
    ],
    [
      "xl/worksheets/sheet1.xml",
      `<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheet}</sheetData></worksheet>`,
    ],
  ];
  const locals: Buffer[] = [];
  const centrals: Buffer[] = [];
  let offset = 0;
  for (const [n, text] of parts) {
    const raw = Buffer.from(text, "utf8");
    const body = deflateRawSync(raw);
    const name = Buffer.from(n, "utf8");
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(8, 8);
    local.writeUInt32LE(crc32(raw) >>> 0, 14);
    local.writeUInt32LE(body.length, 18);
    local.writeUInt32LE(raw.length, 22);
    local.writeUInt16LE(name.length, 26);
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(8, 10);
    central.writeUInt32LE(crc32(raw) >>> 0, 16);
    central.writeUInt32LE(body.length, 20);
    central.writeUInt32LE(raw.length, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt32LE(offset, 42);
    locals.push(local, name, body);
    centrals.push(central, name);
    offset += 30 + name.length + body.length;
  }
  const cd = Buffer.concat(centrals);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(parts.length, 8);
  eocd.writeUInt16LE(parts.length, 10);
  eocd.writeUInt32LE(cd.length, 12);
  eocd.writeUInt32LE(offset, 16);
  return new Uint8Array(Buffer.concat([...locals, cd, eocd]));
}

